	up++
	cnt := up - lo
	var mid, step int64
	for cnt >= eps {
		step = cnt / 2
		mid = lo + step
		if !f(mid) {
			lo = mid + eps
			cnt -= step + eps
		} else {
			cnt = step
		}
	}
	return lo
}

